 ('housing-society.security.visitors','community','released','{}'::uuid[],'housing-society'),('housing-society.security.staff','admin','released','{}'::uuid[],'housing-society'),('housing-society.security.move-approvals','community','released','{}'::uuid[],'housing-society'),('housing-society.assets.registry','admin','released','{}'::uuid[],'housing-society'),('housing-society.compliance.calendar','admin','released','{}'::uuid[],'housing-society'),('housing-society.security.emergency','core','released','{}'::uuid[],'housing-society')
on conflict(feature_key) do update set bundle_key=excluded.bundle_key,rollout_state=excluded.rollout_state,vertical_kind=excluded.vertical_kind;

do $$ begin if to_regclass('public.hs_visitors') is null or to_regclass('public.hs_domestic_staff') is null or to_regclass('public.hs_assets') is null or to_regclass('public.hs_compliance_items') is null then raise exception 'HS-5 compatibility check failed: security/compliance tables missing.';end if;if to_regprocedure('public.hs5_get_snapshot()') is null or to_regprocedure('public.hs5_create_visitor(uuid,text,text,timestamptz,text,text,text)') is null or to_regprocedure('public.hs5_upsert_asset(uuid,text,text,text,text,date)') is null then raise exception 'HS-5 compatibility check failed: RPCs missing.';end if;end $$;
